#!/bin/bash
# #2505 Inkling 2 continuous batching, run ON THE STUDIO by studio-2505.sh (detached, own process
# group) inside a window whose owner already paused live, the runner's Studio target and the FLOP
# miner. This job never pauses, restores or restarts any of them and refuses to start while
# anything still runs.
#
# Steps (STEPS, default "fork provider parity throughput"):
#   fork        clone/fetch Augustas11/mlx-swift-lm into ~/lab-2505/src/mlx-swift-lm at FORK_REF,
#               APFS-clone the tiny Inkling 2 fixtures (generated by #2467's
#               tools/inkling2_parity/make_tiny_fixture.py against mlx-vlm f1618d6d) into its test
#               resources, `swift build --build-tests`, metallib into the .xctest bundles, then
#               `swift test` Inkling2Tests|Inkling2ParityTests|Inkling2BatchRowTests on the CPU and
#               Inkling2ParityTests|Inkling2BatchRowTests with INKLING2_PARITY_DEVICE=gpu;
#   provider    phase3-binary debug `swift build --build-tests` and `swift test` on
#               PagedKVInkling2Tests|PagedKVSlidingWindowTests|PagedKVRuntimeBridge, then the
#               lab-harness release build (-DMACPROVIDER_LAB_HARNESS) used by the next steps;
#   parity      msb-throughput --engine scheduler --scenario parity, 4 rows: synthetic 1024-token
#               prompts and one ragged cohort (700/1500/2100/3000 tokens, rings wrap at different
#               columns), 256 greedy tokens each, batched vs serial;
#   throughput  msb-throughput --engine scheduler at --rows 1, 2, 4 (1024-token prompts) and 4
#               (8192-token prompts), 256 timed decode tokens, 3 runs: aggregate decode tok/s
#               against the same build's one-row engine and the production serial path.
# Model: mlx-community/Inkling-2-Mini-oQ4e-mtp @ 3eea0427 (MODEL). The provider builds against the
# fork checkout at FORK_REF through `swift package edit` (the campaign moves the Package.resolved
# pin with scripts/bump-mlx-swift-lm-pin.py at freeze, after PR 2507's pin lands).
# Every failure prints `BLOCKER:`; the last line is T2505 rc=<n> PASS|FAIL.
set -u
export PATH=/usr/sbin:/opt/homebrew/bin:/usr/bin:/bin
export DEVELOPER_DIR=$HOME/Applications/Xcode.app/Contents/Developer
RUN_ID=${RUN_ID:?RUN_ID unset}
SRC=${SRC:?SRC unset}
COMMIT=${COMMIT:?COMMIT unset}
FORK_REF=${FORK_REF:?FORK_REF unset}
STEPS=${STEPS:-fork provider parity throughput}
L=$HOME/lab-2505
PKG=$SRC/phase3-binary
HERE=$SRC/scripts/lab/2505
OUT=$L/results/$RUN_ID
MODEL=${MODEL:-$HOME/lab-2467/models/Inkling-2-Mini-oQ4e-mtp@3eea0427}
FIXTURES=${FIXTURES:-$HOME/lab-2467/src-10584fc0d79c/fork/Tests/MLXLMTests/Resources/inkling2}
BUILD=.build-lab-2505
BIN=$PKG/$BUILD/release
MIN_FREE_GB=${MIN_FREE_GB:-40}
FAILED=0
mkdir -p "$OUT" "$L/src"
say() { echo "$(date '+%H:%M:%S') $*"; }
done_rc() { say "T2505 rc=$1 $([ "$1" = 0 ] && echo PASS || echo FAIL)"; exit "$1"; }
die() { say "BLOCKER: $1"; done_rc "${2:-90}"; }
blocker() { say "BLOCKER: $*"; FAILED=1; }
has() { case " $STEPS " in *" $1 "*) return 0 ;; esac; return 1; }
listening() { lsof -nP -iTCP:"$1" -sTCP:LISTEN -t >/dev/null 2>&1; }

# Preflight.
listening 8080 && die "a server listens on :8080; the Studio is not paused" 3
listening 8000 && die "a server listens on :8000; the FLOP miner backend is not paused" 3
launchctl print "gui/$(id -u)/live.malibu.provider" >/dev/null 2>&1 && die "live.malibu.provider is loaded" 3
pgrep -f "[m]acprovider-cli serve" >/dev/null 2>&1 && die "a macprovider-cli serve process runs" 3
launchctl list 2>/dev/null | grep -q 'com\.flop\.' && die "a com.flop LaunchAgent is loaded (miner not paused)" 3
free_gb=$(df -g "$HOME" | awk 'NR==2{print $4}')
[ "${free_gb:-0}" -ge "$MIN_FREE_GB" ] || die "only ${free_gb:-?} GB free (need $MIN_FREE_GB)" 13
[ -d "$DEVELOPER_DIR" ] || die "no DEVELOPER_DIR at $DEVELOPER_DIR" 92
[ -f "$MODEL/config.json" ] || die "no model at $MODEL" 11
say "JOB_START run=$RUN_ID commit=$COMMIT fork=$FORK_REF steps=\"$STEPS\" free=${free_gb}GB model=$MODEL ($(du -sh "$MODEL" | cut -f1)) swift=$(swift --version 2>&1 | head -1)"

# Fork: build and the Inkling 2 tests, CPU then GPU.
R=$L/src/mlx-swift-lm
if has fork; then
  if [ ! -d "$R/.git" ]; then
    git clone -q https://github.com/Augustas11/mlx-swift-lm.git "$R" || die "fork clone failed" 93
  fi
  git -C "$R" fetch -q origin macprovider/2505-inkling2-cb || die "fork fetch failed" 93
  git -C "$R" checkout -q --detach "$FORK_REF" || die "cannot check out $FORK_REF" 93
  say "FORK $(git -C "$R" rev-parse --short HEAD): $(git -C "$R" log -1 --format=%s)"
  for f in tiny-oq tiny-source; do
    [ -f "$FIXTURES/$f/config.json" ] || die "no tiny fixture $FIXTURES/$f" 11
    rm -rf "$R/Tests/MLXLMTests/Resources/inkling2/$f"
    /bin/cp -c -R "$FIXTURES/$f" "$R/Tests/MLXLMTests/Resources/inkling2/$f" || die "fixture copy failed" 11
  done
  say "FORK_BUILD swift build --build-tests"
  (cd "$R" && swift build --build-tests) > "$OUT/fork-build.log" 2>&1 \
    || { grep -E "error:" "$OUT/fork-build.log" | sort -u | head -40; die "fork build failed" 14; }
  mkdir -p "$OUT/fork-metallib"
  MLX_SWIFT_CHECKOUT="$R/.build/checkouts/mlx-swift" bash "$PKG/scripts/build-mlx-metallib.sh" "$OUT/fork-metallib" \
    > "$OUT/fork-metallib.log" 2>&1 || die "fork metallib build failed: $(tail -3 "$OUT/fork-metallib.log" | tr '\n' ' ')" 94
  for x in "$R"/.build/arm64-apple-macosx/debug/*.xctest/Contents/MacOS; do cp "$OUT/fork-metallib/mlx.metallib" "$x/"; done
  say "FORK_TEST cpu"
  (cd "$R" && swift test --skip-build --filter 'Inkling2Tests|Inkling2ParityTests|Inkling2BatchRowTests') \
    > "$OUT/fork-test-cpu.log" 2>&1; rc=$?
  grep -E "Test Case .*failed|recorded an issue|error:|Executed|inkling2 batch rows|skipped" "$OUT/fork-test-cpu.log" | sort -u | tail -40
  [ $rc = 0 ] || blocker "fork CPU tests rc=$rc"
  say "FORK_TEST gpu"
  (cd "$R" && INKLING2_PARITY_DEVICE=gpu swift test --skip-build --filter 'Inkling2ParityTests|Inkling2BatchRowTests') \
    > "$OUT/fork-test-gpu.log" 2>&1; rc=$?
  grep -E "Test Case .*failed|recorded an issue|error:|Executed|inkling2 batch rows|skipped" "$OUT/fork-test-gpu.log" | sort -u | tail -40
  [ $rc = 0 ] || blocker "fork GPU tests rc=$rc"
fi

# Provider: unit tests (debug) and the lab-harness release build.
if has provider; then
  [ "$(git -C "$R" rev-parse HEAD 2>/dev/null)" = "$(git -C "$R" rev-parse "$FORK_REF^{commit}" 2>/dev/null)" ] \
    || die "the fork checkout $R is not at $FORK_REF (run the fork step)" 93
  (cd "$PKG" && swift package --build-path "$BUILD" edit mlx-swift-lm --path "$R") > "$OUT/provider-edit.log" 2>&1 \
    || die "swift package edit mlx-swift-lm failed: $(tail -3 "$OUT/provider-edit.log" | tr '\n' ' ')" 93
  say "PROVIDER_FORK edited mlx-swift-lm -> $R ($(git -C "$R" rev-parse --short HEAD))"
  say "PROVIDER_TEST_BUILD swift build --build-tests"
  (cd "$PKG" && nice -n 10 swift build --build-tests --build-path "$BUILD") > "$OUT/provider-test-build.log" 2>&1 \
    || { grep -E "error:" "$OUT/provider-test-build.log" | sort -u | head -40; die "provider test build failed" 14; }
  mkdir -p "$OUT/metallib"
  MLX_SWIFT_CHECKOUT="$PKG/$BUILD/checkouts/mlx-swift" bash "$PKG/scripts/build-mlx-metallib.sh" "$OUT/metallib" \
    > "$OUT/metallib.log" 2>&1 || die "metallib build failed: $(tail -3 "$OUT/metallib.log" | tr '\n' ' ')" 94
  for x in "$PKG/$BUILD"/arm64-apple-macosx/debug/*.xctest/Contents/MacOS "$PKG/$BUILD/arm64-apple-macosx/debug"; do
    cp "$OUT/metallib/mlx.metallib" "$x/" 2>/dev/null
  done
  say "PROVIDER_TEST"
  (cd "$PKG" && swift test --skip-build --build-path "$BUILD" \
      --filter 'PagedKVInkling2Tests|PagedKVSlidingWindowTests|PagedKVRuntimeBridge|PagedKVRecurrent') \
    > "$OUT/provider-test.log" 2>&1; rc=$?
  grep -E "Test Case .*failed|recorded an issue|error:|Executed|skipped" "$OUT/provider-test.log" | sort -u | tail -40
  [ $rc = 0 ] || blocker "provider tests rc=$rc"
  say "PROVIDER_RELEASE_BUILD lab harness"
  (cd "$PKG" && nice -n 10 swift build -c release --product macprovider-cli --build-path "$BUILD" -Xswiftc -DMACPROVIDER_LAB_HARNESS) \
    > "$OUT/provider-release-build.log" 2>&1 \
    || { grep -E "error:" "$OUT/provider-release-build.log" | sort -u | head -40; die "release build failed" 14; }
  cp "$OUT/metallib/mlx.metallib" "$BIN/mlx.metallib" || die "metallib copy failed" 14
  shasum -a 256 "$BIN/macprovider-cli" "$BIN/mlx.metallib" > "$OUT/identity.sha256"
  say "BUILD_DONE $("$BIN/macprovider-cli" --version 2>&1 | head -1) cli=$(cut -c1-16 "$OUT/identity.sha256" | head -1)"
fi

msb() {  # msb LABEL ARGS...
  local label=$1; shift
  say "CELL_START $label $*"
  (cd "$BIN" && ./macprovider-cli msb-throughput --model "$MODEL" --engine scheduler "$@" --output "$OUT/$label.json") \
    > "$OUT/$label.out" 2> "$OUT/$label.err"
  local rc=$?
  say "CELL_DONE $label rc=$rc $(/usr/bin/python3 -I "$HERE/summarize.py" "$OUT/$label.json" 2>&1 | tr '\n' ' ' | cut -c1-600)"
  [ $rc = 0 ] || blocker "$label rc=$rc: $(tail -n 3 "$OUT/$label.err" | tr '\n' ' ' | cut -c1-400)"
}

if has parity || has throughput; then
  [ -x "$BIN/macprovider-cli" ] || die "no lab-harness binary at $BIN (run the provider step)" 14
fi
if has parity; then
  msb parity-r4-p1024 --scenario parity --rows 4 --prompt-tokens 1024 --parity-tokens 256
  /usr/bin/python3 -I - "$OUT/ragged-prompts.json" <<'PY'
import json, random, sys
rng = random.Random(2505)
prompts = [{"name": f"p{n}", "ids": [rng.randrange(1000, 60000) for _ in range(n)]} for n in (700, 1500, 2100, 3000)]
json.dump({"prompts": prompts}, open(sys.argv[1], "w"))
PY
  msb parity-r4-ragged --scenario parity --rows 4 --prompt-token-file "$OUT/ragged-prompts.json" --parity-tokens 256
fi
if has throughput; then
  for r in 1 2 4; do
    msb tput-r$r-p1024 --scenario throughput --rows "$r" --prompt-tokens 1024 --decode-tokens 256 --runs 3
  done
  msb tput-r4-p8192 --scenario throughput --rows 4 --prompt-tokens 8192 --decode-tokens 256 --runs 3
fi
[ "$FAILED" = 0 ] && done_rc 0
done_rc 1
